<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Crea-Biz EV</title>
<style>body{margin:0;background:#f4f7f8;color:#153438;font:16px system-ui}header{background:#113e43;color:white;padding:1.5rem 5%;display:flex;justify-content:space-between}main{max-width:1100px;margin:auto;padding:2rem}section{background:white;border:1px solid #dbe4e5;border-radius:12px;padding:1.4rem;margin-bottom:1.5rem}h1{font-size:2.4rem}button{background:#126b63;color:white;border:0;border-radius:6px;padding:.8rem;cursor:pointer}input,select{padding:.8rem;border:1px solid #9caeb0;border-radius:6px;max-width:100%;box-sizing:border-box}form,.filters{display:flex;gap:.7rem;flex-wrap:wrap}article{padding:1rem;border-bottom:1px solid #ddd}.badge{display:inline-block;background:#fff0ca;padding:.3rem .6rem;border-radius:20px;font-size:.8rem}#notice{white-space:pre-wrap}label{display:flex;flex-direction:column;gap:.3rem}a{color:inherit}small{display:block;color:#52686b;margin:.5rem 0}[hidden]{display:none!important}</style></head>
<body><header><strong>Crea-Biz / EV</strong><button id="language">العربية</button></header><main>
<h1 data-en="Find your next charge" data-ar="ابحث عن محطة الشحن التالية">Find your next charge</h1>
<p data-en="Station discovery and development reservations. Physical charging and payments are not connected." data-ar="اكتشاف المحطات وحجوزات التطوير. الشحن الفعلي والمدفوعات غير متصلة.">Station discovery and development reservations. Physical charging and payments are not connected.</p>
<p id="notice" role="status" aria-live="polite"></p>
<section id="identity"><h2>Account / الحساب</h2><form id="account"><label>Name / الاسم<input name="name" autocomplete="name"></label><label>Email / البريد<input name="email" type="email" autocomplete="email" required></label><label>Password / كلمة المرور<input name="password" type="password" autocomplete="current-password" minlength="12" required></label><button name="mode" value="login">Sign in / دخول</button><button name="mode" value="register">Register / تسجيل</button></form><div id="signed" hidden><span id="who"></span> <button id="logout">Sign out / خروج</button></div></section>
<section><h2>Stations / المحطات</h2><form id="filters"><label>Connector / الموصل<select name="connector_type"><option value="">All / الكل</option><option>CCS2</option><option>Type2</option><option>CHAdeMO</option></select></label><label>Minimum kW<input name="min_power_kw" type="number" min="1" max="1000"></label><button>Search / بحث</button></form><div id="stations"></div></section>
<section id="bookings" hidden><h2>Reservations / الحجوزات</h2><p>Each development reservation covers one 30-minute UTC slot on the station's single test connector.</p><div id="reservation-list"></div></section>
<section id="vendor" hidden><h2>Vendor station registration / تسجيل محطة</h2><form id="station-form"><label>Name<input name="name" required></label><label>Country<input name="country" value="AE" maxlength="2" required></label><label>Currency<input name="currency" value="AED" maxlength="3" required></label><label>Timezone<input name="timezone" value="Asia/Dubai" required></label><label>Latitude<input name="latitude" type="number" step="any" min="-90" max="90" required></label><label>Longitude<input name="longitude" type="number" step="any" min="-180" max="180" required></label><label>Connector<select name="connector_type"><option>CCS2</option><option>Type2</option><option>CHAdeMO</option></select></label><label>kW<input name="power_kw" type="number" min="1" max="1000" required></label><label>Source<select name="source"><option value="discovery">Discovery only</option><option value="simulator">Simulator inventory</option></select></label><button>Create station</button></form></section>
<section id="simulations" hidden><h2>Simulated charging / الشحن التجريبي</h2><div id="simulation-list"></div></section><section id="admin" hidden><h2>Admin operational overview</h2><pre id="overview"></pre></section></main><script>
let user=null,csrf=document.querySelector('meta[name=csrf-token]').content;
const el=id=>document.getElementById(id),notice=s=>el('notice').textContent=s;
async function api(path,method='GET',data){let r=await fetch('/api/'+path,{method,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:data?JSON.stringify(data):undefined});let j=r.status===204?null:await r.json();if(!r.ok)throw Error(j.message||'Request failed');return j}
function node(tag,text){let e=document.createElement(tag);e.textContent=text;return e}
async function identity(){try{user=await api('me')}catch{user=null}el('account').hidden=!!user;el('signed').hidden=!user;el('bookings').hidden=!user;el('vendor').hidden=user?.role!=='vendor';el('who').textContent=user?user.name+' · '+user.role:'';el('simulations').hidden=!user;el('admin').hidden=user?.role!=='admin';if(user){await bookings();await simulations()}if(user?.role==='admin')el('overview').textContent=JSON.stringify(await api('admin/overview'),null,2)}
async function stations(query=''){let j=await api('stations'+query);el('stations').replaceChildren();if(!j.data.length)el('stations').append(node('p','No stations match. No live network data is connected.'));for(let s of j.data){let a=node('article','');a.append(node('h3',s.name),node('span',s.evidence+' · '+s.availability),node('p',s.connector_type+' · '+s.power_kw+' kW · '+s.country));if(s.reservable&&user?.role==='customer'){let f=document.createElement('form'),l=node('label','UTC start (00 or 30 minutes)'),i=document.createElement('input');i.type='datetime-local';i.step=1800;i.required=true;l.append(i);f.append(l);let b=node('button','Reserve simulator slot');f.append(b);f.onsubmit=async e=>{e.preventDefault();b.disabled=true;try{await api('reservations','POST',{station_id:s.id,starts_at:i.value.length===16?i.value+':00Z':i.value+'Z',idempotency_key:crypto.randomUUID()});notice('Simulation inventory reserved. No physical charger command was sent.');await bookings()}catch(e){notice(e.message)}finally{b.disabled=false}};a.append(f)}el('stations').append(a)}}
async function bookings(){let j=await api('reservations');el('reservation-list').replaceChildren();for(let r of j.data){let a=node('article','#'+r.id+' · station '+r.station_id+' · '+r.starts_at+' UTC · '+r.status);if(user.role==='customer'&&r.status==='confirmed'){let b=node('button','Cancel');b.onclick=async()=>{try{await api('reservations/'+r.id,'DELETE');await bookings()}catch(e){notice(e.message)}};a.append(b);let start=node('button','Start simulator');start.onclick=async()=>{try{await api('reservations/'+r.id+'/simulate-start','POST');await simulations()}catch(e){notice(e.message)}};a.append(start)}el('reservation-list').append(a)}}
async function simulations(){let j=await api('simulations');el('simulation-list').replaceChildren();for(let s of j.data){let a=node('article','SIMULATED · #'+s.id+' · '+s.status+' · '+s.energy_wh+' Wh · '+(s.total_minor??'pending')+' minor units '+s.currency+' · No payment processed');if(s.status==='charging'){let stop=node('button','Stop simulation');stop.onclick=async()=>{try{await api('simulations/'+s.id+'/stop','POST');await simulations()}catch(e){notice(e.message)}};a.append(stop);if(user.role==='vendor'){let f=document.createElement('form'),i=document.createElement('input');i.type='number';i.min=s.energy_wh;i.max=1000000;i.required=true;i.setAttribute('aria-label','Simulated cumulative energy in Wh');let b=node('button','Submit simulated meter (Wh)');f.append(i,b);f.onsubmit=async e=>{e.preventDefault();try{await api('simulations/'+s.id+'/meter','PUT',{energy_wh:Number(i.value)});await simulations()}catch(e){notice(e.message)}};a.append(f)}}el('simulation-list').append(a)}}
el('account').onsubmit=async e=>{e.preventDefault();try{await api(e.submitter.value,'POST',Object.fromEntries(new FormData(e.target)));csrf=(await api('csrf')).token;await identity();await stations();notice('Signed in.')}catch(e){notice(e.message)}};
el('logout').onclick=async()=>{await api('logout','POST');csrf=(await api('csrf')).token;await identity();await stations()};
el('filters').onsubmit=e=>{e.preventDefault();let q=new URLSearchParams();for(let [k,v]of new FormData(e.target))if(v)q.set(k,v);stations('?'+q).catch(e=>notice(e.message))};
el('station-form').onsubmit=async e=>{e.preventDefault();try{await api('stations','POST',Object.fromEntries(new FormData(e.target)));await stations();notice('Station registered.')}catch(e){notice(e.message)}};
el('language').onclick=()=>{let ar=document.documentElement.lang!=='ar';document.documentElement.lang=ar?'ar':'en';document.documentElement.dir=ar?'rtl':'ltr';document.querySelectorAll('[data-en]').forEach(n=>n.textContent=n.dataset[ar?'ar':'en'])};
(async()=>{await identity();await stations()})().catch(e=>notice(e.message));
</script></body></html>